class Solution { private lateinit var parent:IntArray;private lateinit var size:IntArray;private fun find(valueValue:Int):Int{var value=valueValue;while(value!=parent[value]){parent[value]=parent[parent[value]];value=parent[value]};return value};private fun union(firstValue:Int,secondValue:Int){var first=find(firstValue);var second=find(secondValue);if(first==second)return;if(size[first]<size[second]){val temporary=first;first=second;second=temporary};parent[second]=first;size[first]+=size[second]};fun latestDayToCross(row:Int,col:Int,cells:Array<IntArray>):Int{val total=row*col;val top=total;val bottom=total+1;parent=IntArray(total+2){it};size=IntArray(total+2){1};val land=BooleanArray(total);val directions=arrayOf(intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));for(day in cells.lastIndex downTo 0){val r=cells[day][0]-1;val c=cells[day][1]-1;val index=r*col+c;land[index]=true;if(r==0)union(index,top);if(r==row-1)union(index,bottom);for(direction in directions){val nr=r+direction[0];val nc=c+direction[1];if(nr in 0 until row&&nc in 0 until col&&land[nr*col+nc])union(index,nr*col+nc)};if(find(top)==find(bottom))return day};return 0} }
